<?php $manage = can('printers.manage'); ?>
<div class="top"><div><h2 style="margin:0">Print queue</h2><span class="muted"><a href="/staff/printers">Printers</a> &middot; Jobs are added from an order page.</span></div></div>
<div class="card mb"><h3>Waiting and printing</h3><div class="tw"><table><tr><th>Job</th><th>Order</th><th>Printer</th><th>Material</th><th>Planned</th><th>Est.</th><th>Status</th><?= $manage ? '<th></th>' : '' ?></tr>
<?php foreach ($jobs as $j): $late = $j['due_date'] && $j['due_date'] < date('Y-m-d'); ?><tr><td>#<?= (int) $j['id'] ?></td><td><a href="/staff/requests/<?= (int) $j['request_id'] ?>"><?= e($j['ref']) ?></a> <span class="muted"><?= e($j['cname']) ?></span></td><td><?= e((string) ($j['pname'] ?? 'unassigned')) ?></td><td><?= e($j['material']) ?> &times;<?= (int) $j['quantity'] ?></td>
<td class="<?= $late ? 'overdue' : '' ?>"><?= e(fmt_date($j['scheduled_for'])) ?><?= $late ? ' (order late)' : '' ?></td><td><?= $j['est_hours'] ? e($j['est_hours']) . ' h' : '' ?> <?= $j['est_grams'] ? e($j['est_grams']) . ' g' : '' ?></td><td><?= badge($j['status'] === 'printing' ? 'Printing' : 'Queued', $j['status'] === 'printing' ? 'p-info' : '') ?></td>
<?php if ($manage): ?><td style="white-space:nowrap"><?php if ($j['status'] === 'queued'): ?><form method="post" action="/staff/jobs/<?= (int) $j['id'] ?>" class="inline"><?= csrf_field() ?><input type="hidden" name="action" value="start"><button class="btn sm">Start</button></form> <?php endif; ?>
<form method="post" action="/staff/jobs/<?= (int) $j['id'] ?>" class="inline"><?= csrf_field() ?><input type="hidden" name="action" value="finish"><input name="actual_hours" inputmode="decimal" placeholder="hours" value="<?= e((string) $j['est_hours']) ?>" style="width:70px;margin:0" aria-label="Actual hours"> <input name="actual_grams" inputmode="decimal" placeholder="grams" value="<?= e((string) $j['est_grams']) ?>" style="width:80px;margin:0" aria-label="Actual grams"> <button class="btn sm alt">Finish</button></form>
<form method="post" action="/staff/jobs/<?= (int) $j['id'] ?>" class="inline"><?= csrf_field() ?><input type="hidden" name="action" value="fail"><button class="btn sm danger" data-confirm="Mark this job as failed?">Failed</button></form></td><?php endif; ?></tr>
<?php endforeach; if (!$jobs): ?><tr><td colspan="8" class="muted">Nothing in the queue.</td></tr><?php endif; ?></table></div></div>
<div class="card mb"><h3>Next 14 days</h3><div class="tw"><table><tr><th>Printer</th><?php foreach ($days as $d): ?><th><?= e(date('D j', strtotime($d))) ?></th><?php endforeach; ?></tr>
<?php foreach ($printers as $p): ?><tr><td><?= e($p['name']) ?><?= $p['status'] !== 'active' ? ' <span class="muted">(' . e($p['status']) . ')</span>' : '' ?></td><?php foreach ($days as $d): ?><td><?php foreach ($cal[(int) $p['id']][$d] ?? [] as $j): ?><a class="pill <?= $j['status'] === 'done' ? 'p-ok' : ($j['status'] === 'printing' ? 'p-info' : '') ?>" href="/staff/requests/<?= (int) $j['id'] ?>" style="display:block;margin-bottom:2px" title="job #<?= (int) $j['id'] ?>"><?= e($j['ref']) ?></a><?php endforeach; ?></td><?php endforeach; ?></tr>
<?php endforeach; if (!$printers): ?><tr><td colspan="15" class="muted">Add printers first.</td></tr><?php endif; ?></table></div></div>
<div class="card"><h3>Recently finished</h3><div class="tw"><table><?php foreach ($recent as $j): ?><tr><td>#<?= (int) $j['id'] ?></td><td><a href="/staff/requests/<?= (int) $j['request_id'] ?>"><?= e($j['ref']) ?></a></td><td><?= e((string) $j['pname']) ?></td><td><?= $j['status'] === 'done' ? badge('Done', 'p-ok') : badge('Failed', 'p-bad') ?></td><td><?= $j['actual_hours'] !== null ? e($j['actual_hours']) . ' h' : '' ?> <?= $j['actual_grams'] !== null ? e($j['actual_grams']) . ' g' : '' ?></td><td><?= e(fmt_dt($j['finished_at'])) ?></td></tr><?php endforeach; if (!$recent): ?><tr><td class="muted">Nothing yet.</td></tr><?php endif; ?></table></div></div>
